CREATE OR REPLACE FUNCTION public.daily_match_checkin_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid:=auth.uid(); v public.daily_match_checkins%rowtype; v_streak int;
begin
 if v_uid is null then return jsonb_build_object('authenticated',false); end if;
 select * into v from public.daily_match_checkins where user_id=v_uid;
 if not found then return jsonb_build_object('authenticated',true,'streak',0,'checked_today',false,'total_checkins',0,'completed_weeks',0); end if;
 v_streak:=case when v.last_checkin is null or v.last_checkin < current_date-1 then 0 else v.streak end;
 return jsonb_build_object('authenticated',true,'streak',v_streak,'checked_today',v.last_checkin=current_date,'last_checkin',v.last_checkin,'total_checkins',v.total_checkins,'completed_weeks',v.completed_weeks);
end $function$

CREATE OR REPLACE FUNCTION public.match_credits()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_uid uuid := auth.uid();
    v_bal integer;
begin
    if v_uid is null then
        return jsonb_build_object('authenticated', false, 'credits', 0);
    end if;
    select credits into v_bal from public.profiles where id = v_uid;
    return jsonb_build_object('authenticated', true, 'credits', coalesce(v_bal, 0));
end;
$function$

CREATE OR REPLACE FUNCTION public.request_account_deletion()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid := auth.uid();
  mail text;
begin
  if uid is null then
    raise exception 'Sign in required';
  end if;
  select email into mail from auth.users where id = uid;
  insert into public.account_deletion_requests(user_id, email)
  values (uid, coalesce(mail, ''))
  on conflict (user_id) do update
    set requested_at = now(),
        purge_after = now() + interval '72 hours',
        purged_at = null;
  begin
    update public.profiles
       set profile_locked = true
     where id = uid;
  exception when undefined_table then
    null;
  end;
  return jsonb_build_object(
    'ok', true,
    'purge_after_hours', 72,
    'message', 'Deletion scheduled. The same email can register again after 72 hours.'
  );
end;
$function$
